/* Example: basic element styling */
.target-box {
    width: 150px;
    height: 150px;
    background-color: #e74c3c;
}

/* Example of applying a CSS property to an element */
div {
    color: blue;
    font-size: 16px;
}

/* Moving an element with translate */
.element {
    transform: translate(20px, 10px);
}

/* Similar: scaling an element */
.element {
    transform: scale(1.5);
}

/* Similar: scaling an element horizontally */
.element {
    transform: scaleX(2);
}

/* Similar: applying a rotation */
.element {
    transform: rotate(30deg);
}

/* Example: combining transformations */
.element {
    transform: translate(50px, 20px) rotate(45deg);
}

/* Example of multiple transformations */
.element {
    transform: translate(10px, 10px) scale(2) rotate(30deg);
}

/* Example of changing transformation order */
.element {
    transform: scale(1.5) rotate(45deg) translate(50px, 30px);
}

/* Example of changing transformation order */
.element {
    transform: scale(1.5) rotate(45deg) translate(50px, 30px);
}

/* Example of adding a transition for smooth effects */
.element {
    transition: transform 0.3s ease;
}
